import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"].copy()
    stg = inputs["stg_account"].copy()

    # Build initial per-account version lists from existing dim_account
    versions = {}
    for _, row in dim.iterrows():
        acc = row["account_id"]
        versions.setdefault(acc, []).append({
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"] if pd.notna(row["eff_end_date"]) else None,
            "is_current": int(row["is_current"]),
        })

    # Sort staged records by (account_id, update_date) ascending
    stg_sorted = stg.sort_values(by=["account_id", "update_date"], kind="mergesort")

    def plans_equal(p1, p2):
        n1 = pd.isna(p1)
        n2 = pd.isna(p2)
        if n1 and n2:
            return True
        if n1 != n2:
            return False
        return p1 == p2

    for _, srow in stg_sorted.iterrows():
        acc = srow["account_id"]
        plan = srow["plan"]
        d = srow["update_date"]

        vlist = versions.setdefault(acc, [])

        if len(vlist) == 0:
            vlist.append({
                "plan": plan,
                "eff_start_date": d,
                "eff_end_date": None,
                "is_current": 1,
            })
            continue

        # Find covering version
        v = None
        for cand in vlist:
            start = cand["eff_start_date"]
            end = cand["eff_end_date"]
            if start <= d and (end is None or d < end):
                v = cand
                break

        if v is None:
            # update_date earlier than the earliest version
            f = min(vlist, key=lambda x: x["eff_start_date"])
            vlist.append({
                "plan": plan,
                "eff_start_date": d,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            if plans_equal(v["plan"], plan):
                # no-op
                pass
            elif d == v["eff_start_date"]:
                v["plan"] = plan
            else:
                new_v = {
                    "plan": plan,
                    "eff_start_date": d,
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                }
                vlist.append(new_v)
                v["eff_end_date"] = d
                v["is_current"] = 0

    # Flatten all versions into output rows
    out_rows = []
    for acc, vlist in versions.items():
        for v in vlist:
            out_rows.append({
                "account_id": acc,
                "plan": v["plan"],
                "eff_start_date": v["eff_start_date"],
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            })

    out_df = pd.DataFrame(out_rows, columns=[
        "account_id", "plan", "eff_start_date", "eff_end_date", "is_current"
    ])

    if len(out_df) > 0:
        out_df["account_id"] = out_df["account_id"].astype("int64")
        out_df["is_current"] = out_df["is_current"].astype("int64")
        out_df["eff_start_date"] = pd.to_datetime(out_df["eff_start_date"])
        out_df["eff_end_date"] = pd.to_datetime(out_df["eff_end_date"])
        out_df = out_df.sort_values(
            by=["account_id", "eff_start_date"], kind="mergesort"
        ).reset_index(drop=True)
    else:
        out_df = out_df.astype({
            "account_id": "int64",
            "plan": "object",
            "eff_start_date": "datetime64[us]",
            "eff_end_date": "datetime64[us]",
            "is_current": "int64",
        })

    return {"dim_account_out": out_df}
